"""The static site's data, generated by the serving layer itself (D-044).

Every number comes from a ServingService call, the same code the dashboard runs, so the page
only displays and slices. Files (paths relative to the site root):

- data/index.json: model and dataset metadata, per-step metrics and the guided tour.
  Everything the first screen needs, in one small file.
- data/steps/{t}.json: the step's top alerts, its communities, and the neighbourhoods of its
  demo alerts at every hop setting, with build-time node positions.
- data/shap/{t}-{s}.json: transaction detail (score, flag, top SHAP values) for the step's
  transactions with tx_id % shards == s, fetched only when one is opened.
- data/lookup.json: tx_id -> step, fetched only for a search by ID.
"""

from pathlib import Path

import networkx as nx

from fraudgraph.config import load_config
from fraudgraph.serving.artifacts import load_artifacts
from fraudgraph.serving.graph import InMemoryStore
from fraudgraph.serving.service import Limits, ServingService

TOUR_STEPS = (40, 43)  # before and after the shutdown, as in the dashboard's tour
CANVAS, MARGIN = 1000, 110  # SVG units; the margin leaves room for the star and its label


def demo_service(folder: Path) -> ServingService:
    """The dashboard's in-process service over an exported demo folder."""
    data = load_artifacts(folder)
    limits = Limits(**load_config("serving")["limits"])
    return ServingService(data, InMemoryStore(data.edges, data.transactions), limits)


def layout_positions(neighbourhood: dict, seed: int) -> list[list[float]]:
    """Seeded spring layout, scaled to the SVG canvas, in the order of the nodes list.

    The dashboard's pyvis graph lays nodes out with live physics, differently on each load;
    here positions are fixed at build time (D-045). Nodes and edges are the same.
    """
    ids = [n["tx_id"] for n in neighbourhood["nodes"]]
    if len(ids) == 1:
        return [[CANVAS / 2, CANVAS / 2]]
    g = nx.Graph()
    g.add_nodes_from(ids)
    g.add_edges_from((e["src"], e["dst"]) for e in neighbourhood["edges"])
    pos = nx.spring_layout(g, seed=seed)
    xs, ys = [pos[t][0] for t in ids], [pos[t][1] for t in ids]
    # One scale for both axes, centred, so a small graph keeps its shape instead of being
    # stretched into the corners.
    span = max(max(xs) - min(xs), max(ys) - min(ys)) or 1
    size = CANVAS - 2 * MARGIN
    cx, cy = (max(xs) + min(xs)) / 2, (max(ys) + min(ys)) / 2

    def place(v, centre):
        return round(CANVAS / 2 + (v - centre) / span * size, 1)

    return [[place(x, cx), place(y, cy)] for x, y in zip(xs, ys, strict=True)]


def expand_transaction(entry: dict, shard: dict, meta: dict) -> dict:
    """A shard entry back in ServingService.transaction's shape. The page does the same."""
    return {
        "tx_id": entry["tx_id"],
        "time_step": shard["time_step"],
        "risk_score": entry["risk_score"],
        "flagged": entry["flagged"],
        "label": None,  # the demo ships no labels (D-040)
        "threshold": meta["threshold"],
        "base_value": meta["base_value"],
        "top_features": [
            {"feature": meta["features"][i], "group": meta["groups"][i], "shap": v}
            for i, v in entry["top"]
        ],
    }


def build_site_data(
    service: ServingService, dataset: dict, alerts_k: int, shards_per_step: int, layout_seed: int
) -> dict[str, dict]:
    """Site path -> JSON payload, for the demo export behind `service`."""
    meta = service.meta()
    roots = meta["neighbourhood_roots"]
    if not meta["demo"] or roots is None:
        raise ValueError("The static site is built from the public demo export only (D-040)")
    tx = service.data.transactions
    shap = service.data.shap
    features = sorted(shap["feature"].unique())
    group_of = dict(zip(shap["feature"], shap["group"], strict=True))
    feature_index = {f: i for i, f in enumerate(features)}
    first, last = meta["steps"]

    def in_range(step: int) -> int:
        return min(max(step, first), last)

    before, after = (in_range(s) for s in TOUR_STEPS)
    out: dict[str, dict] = {
        "data/index.json": {
            "meta": meta
            | {
                "dataset_repo": dataset["repo"],
                "dataset_revision": dataset["revision"],
                "base_value": float(service.data.meta["base_value"]),
                "features": features,
                "groups": [group_of[f] for f in features],
                "alerts_k": alerts_k,
                "shards_per_step": shards_per_step,
            },
            "steps": service.steps()["steps"],
            "tour": {
                "before": before,
                "after": after,
                "alert": service.alerts(before, 1)["alerts"][0],
            },
        },  # fmt: skip
        "data/lookup.json": {
            str(step): sorted(int(t) for t in ids)
            for step, ids in tx.groupby("time_step").groups.items()
        },
    }
    step_of = tx["time_step"]
    for t in range(first, last + 1):
        neighbourhoods = {}
        for root in (r for r in roots if int(step_of[r]) == t):
            neighbourhoods[str(root)] = {}
            for hops in range(1, meta["max_hops"] + 1):
                nb = service.neighbourhood(root, hops)
                neighbourhoods[str(root)][str(hops)] = nb | {
                    "positions": layout_positions(nb, layout_seed)
                }
        out[f"data/steps/{t}.json"] = {
            "time_step": t,
            "alerts": service.alerts(t, alerts_k)["alerts"],
            "communities": service.communities(t, 5, 10),
            "neighbourhoods": neighbourhoods,
        }
        shards = {s: [] for s in range(shards_per_step)}
        for tx_id in sorted(tx.index[step_of == t]):
            d = service.transaction(int(tx_id))
            shards[int(tx_id) % shards_per_step].append(
                {"tx_id": d["tx_id"], "risk_score": d["risk_score"], "flagged": d["flagged"],
                 "top": [[feature_index[f["feature"]], f["shap"]] for f in d["top_features"]]}
            )  # fmt: skip
        for s, entries in shards.items():
            out[f"data/shap/{t}-{s}.json"] = {"time_step": t, "transactions": entries}
    return out
